# Rule: period p = #bands; output[r][all cols] = color of the band whose row == r mod p.
def f(g):
    h,w=len(g),len(g[0])
    bands=[(r,g[r][0]) for r in range(h) if g[r][0]!=0]
    p=len(bands)
    m={r%c:c for r,c in bands}
    return [[m[r%p] for _ in range(w)] for r in range(h)]
